import { unique } from "./utils.js";

export function buildMermaidGraph(automations) {
  const lines = [
    "flowchart LR",
    "  %% Generated by HassTangle",
    "  classDef automation fill:#14213d,stroke:#5cc8ff,color:#ffffff;",
    "  classDef entity fill:#f8f4e3,stroke:#e09f3e,color:#1f2937;",
  ];
  const automationIds = new Map();
  automations.forEach((automation, index) => {
    const nodeId = `a${index}`;
    automationIds.set(automation.key, nodeId);
    lines.push(
      `  ${nodeId}["${escapeMermaid(automation.alias)}"]:::automation`,
    );
  });

  const entities = unique(
    automations.flatMap((automation) => [
      ...automation.triggers.flatMap((trigger) => trigger.entities),
      ...automation.writes.map((write) => write.entity),
    ]),
  ).sort();
  const entityIds = new Map();
  entities.forEach((entity, index) => {
    const nodeId = `e${index}`;
    entityIds.set(entity, nodeId);
    lines.push(`  ${nodeId}(("${escapeMermaid(entity)}")):::entity`);
  });

  const edges = new Set();
  for (const automation of automations) {
    const automationId = automationIds.get(automation.key);
    for (const trigger of automation.triggers.filter((item) => item.enabled)) {
      for (const entity of trigger.entities) {
        const label = trigger.to ? `triggers: ${trigger.to}` : "triggers";
        edges.add(
          `  ${entityIds.get(entity)} -- "${escapeMermaid(label)}" --> ${automationId}`,
        );
      }
    }
    for (const write of automation.writes) {
      edges.add(
        `  ${automationId} -- "writes: ${escapeMermaid(write.effect)}" --> ${entityIds.get(write.entity)}`,
      );
    }
  }
  lines.push(...[...edges].sort());
  return `${lines.join("\n")}\n`;
}

function escapeMermaid(value) {
  return String(value)
    .replaceAll("\\", "\\\\")
    .replaceAll('"', "'")
    .replaceAll("\n", " ");
}
